SELECT COUNT(*) AS vehicle_count
FROM vehicles
WHERE year >= 2020;

SELECT AVG(surge_multiplier) AS avg_surge_multiplier
FROM rides
WHERE status = 'completed';

SELECT MAX(distance_km) AS max_distance_km
FROM rides
WHERE status = 'completed';

SELECT
  ROUND(
    100.0 * COUNT(*) FILTER (WHERE payment_method = 'apple_pay') / COUNT(*),
    2
  ) AS apple_pay_percentage
FROM payments;

SELECT AVG(EXTRACT(EPOCH FROM (pickup_time - requested_at)) / 60.0) AS avg_wait_time_minutes
FROM rides
WHERE status = 'completed';
